def normalize_name(value):
    """Minusculas, sin tildes y con espacios simples para comparar nombres."""

    text = unicodedata.normalize("NFKD", str(value or ""))
    text = "".join(char for char in text if not unicodedata.combining(char))
    return " ".join(text.lower().split())


def country_code_for(name):
    """Devuelve el codigo ISO del pais o cadena vacia si no se reconoce."""

    return COUNTRY_CODES_BY_NAME.get(normalize_name(name), "")


def _name(obj, max_length):
    """Nombre limpio del objeto de catalogo, recortado al largo del campo."""

    if obj is None:
        return ""
    return " ".join(str(obj.name or "").split())[:max_length]


def location_values_for(user):
    """Calcula los campos de texto a partir de las relaciones actuales.

    Si faltan pais o provincia se derivan de la ciudad, y la ciudad del campus
    cuando el usuario no tiene ciudad propia, igual que hacia el registro
    historico al resolver la ubicacion desde la ciudad.
    """

    city = user.city
    if city is None and user.campus is not None:
        city = user.campus.city
    province = user.province or (city.province if city is not None else None)
    country = user.country or (province.country if province is not None else None)

    country_name = _name(country, 100)
    return {
        "country_code": country_code_for(country_name),
        "country_name": country_name,
        "province_name": _name(province, 100),
        "city_name": _name(city, 150),
        "university_name": _name(user.university, 200),
    }


def copy_location_to_text(apps, schema_editor):
    """Copia la ubicacion de las claves foraneas a los campos de texto."""

    User = apps.get_model("user", "User")
    users = User.objects.select_related(
        "country",
        "province__country",
        "city__province__country",
        "university",
        "campus__city__province__country",
    )
    for user in users.iterator():
        values = location_values_for(user)
        if any(values.values()):
            User.objects.filter(pk=user.pk).update(**values)


